/**
 * generated by stackra gen from the group folders under src/ (routes, blocks, menus, flags,
 * analytics; no root module file, so the member is the one module `web`), src/config/*.config.ts,
 * stackra.config.ts (targets, render, area) and the drivers of the installed packages — do not
 * edit
 * Purpose: the container wiring of @acme/web for the web target, on the Worker and in the browser:
 *          modules, bindings with their dependencies, each site config override bound in place of
 *          its base, the contexts `createApp` mounts in graph order, and the driver candidates.
 * Boundary: derived from the classes and their constructor parameter types at build time; no
 *           reflect-metadata, no provider list in app code (ADR 0263). A class with no `@Lifetime`
 *           is a singleton; a port with one candidate has no selector. The Workers cache driver
 *           holds the query data the routes cache by profile, keyed by query, input, site, locale,
 *           market and version, with one origin call per key on concurrent misses (ADR 0297 d3).
 * Runtime: isomorphic
 */
import { type Wiring } from "@stackra/container";
import { AnalyticsConfig as BaseAnalyticsConfig } from "@stackra/analytics";
import { AnalyticsDriver } from "@stackra/analytics/contracts";
import { Cache } from "@stackra/cache/contracts";
import { ConsentConfig as BaseConsentConfig } from "@stackra/consent";
import { ConsentStore } from "@stackra/consent/contracts";
import { CspConfig as BaseCspConfig } from "@stackra/csp";
import { Renderer } from "@stackra/experience/contracts";
import { FeatureFlagsConfig as BaseFeatureFlagsConfig } from "@stackra/feature-flags";
import { FlagProvider } from "@stackra/feature-flags/contracts";
import { I18nConfig as BaseI18nConfig } from "@stackra/i18n";
import { TelemetryConfig as BaseTelemetryConfig } from "@stackra/logger";
import { CaptchaVerifier } from "@stackra/platform/contracts";
import { SeoConfig as BaseSeoConfig } from "@stackra/seo";
import { OgRenderer } from "@stackra/seo/contracts";
import { ThemingConfig as BaseThemingConfig } from "@stackra/theming";
import { AnalyticsConfig } from "#src/config/analytics.config";
import { ConsentConfig } from "#src/config/consent.config";
import { CspConfig } from "#src/config/csp.config";
import { EdgeConfig } from "#src/config/edge.config";
import { EnvConfig } from "#src/config/env.config";
import { FeatureFlagsConfig } from "#src/config/feature-flags.config";
import { I18nConfig } from "#src/config/i18n.config";
import { SeoConfig } from "#src/config/seo.config";
import { SiteConfig } from "#src/config/site.config";
import { TelemetryConfig } from "#src/config/telemetry.config";
import { ThemingConfig } from "#src/config/theming.config";
import { SiteMenu } from "#src/menus/site.menu";
import { LandingRoute } from "#src/routes/landing/landing.route";
import { PricingRoute } from "#src/routes/pricing/pricing.route";
import { SiteLayout } from "#src/routes/site/site.layout";
import { StoreRoute } from "#src/routes/store/store.route";

/** Driver names gen found (drivers/ classes); `DriverName<Port>` fields are typed by this. */
declare module "@stackra/container" {
  interface DriverRegistry {
    "analytics.AnalyticsDriver": "posthog" | "none" | "memory";
    "feature_flags.FlagProvider": "config" | "posthog";
  }
}

export const wiring = {
  member: "@acme/web",
  root: "web",
  modules: {
    web: {
      exports: [],
      dependsOn: [
        "clients",
        "cache",
        "i18n",
        "theming",
        "navigation",
        "experience",
        "content",
        "media",
        "money",
        "consent",
        "analytics",
        "logger",
        "errors",
        "feature_flags",
        "seo",
        "csp",
        "platform",
      ],
    },
  },
  bindings: [
    { module: "web", provide: SiteLayout, kind: "layout", deps: [SiteConfig, BaseI18nConfig] },
    { module: "web", provide: SiteMenu, kind: "menu", deps: [SiteConfig] },
    { module: "web", provide: LandingRoute, kind: "route", deps: [SiteConfig] },
    { module: "web", provide: PricingRoute, kind: "route", deps: [SiteConfig] },
    { module: "web", provide: StoreRoute, kind: "route", deps: [BaseSeoConfig] },
  ],
  /**
   * Config classes: the site's own, then each package base (imported as `Base<Name>`) with the
   * override that replaces it across the app; a package's context reads its base and gets the
   * override. `EnvConfig`'s package-named fields feed the overrides after their defaults.
   */
  config: [
    { key: "web.env", provide: EnvConfig },
    { key: "web.site", provide: SiteConfig },
    { key: "web.edge", provide: EdgeConfig },
    { key: "feature_flags", provide: BaseFeatureFlagsConfig, override: FeatureFlagsConfig },
    { key: "theming", provide: BaseThemingConfig, override: ThemingConfig },
    { key: "i18n", provide: BaseI18nConfig, override: I18nConfig },
    { key: "consent", provide: BaseConsentConfig, override: ConsentConfig },
    { key: "analytics", provide: BaseAnalyticsConfig, override: AnalyticsConfig },
    { key: "logger.telemetry", provide: BaseTelemetryConfig, override: TelemetryConfig },
    { key: "seo", provide: BaseSeoConfig, override: SeoConfig },
    { key: "csp", provide: BaseCspConfig, override: CspConfig },
  ],
  /** Mounted by `createApp` outermost first, from the config classes in the module graph. */
  contexts: ["feature_flags", "theming", "i18n", "consent", "analytics", "logger.telemetry", "ui"],
  drivers: [
    {
      port: Cache,
      candidates: {
        workers: () => import("@stackra/cache/worker").then((m) => m.WorkersCacheDriver),
      },
    },
    {
      port: ConsentStore,
      candidates: {
        cookie: () => import("@stackra/consent").then((m) => m.CookieConsentStoreDriver),
      },
    },
    {
      port: AnalyticsDriver,
      selectedBy: "config:analytics.driver",
      candidates: {
        posthog: () => import("@stackra/analytics").then((m) => m.PosthogAnalyticsDriver),
        none: () => import("@stackra/analytics").then((m) => m.NoneAnalyticsDriver),
        memory: () => import("@stackra/analytics").then((m) => m.MemoryAnalyticsDriver),
      },
    },
    {
      port: FlagProvider,
      selectedBy: "config:feature_flags.provider",
      candidates: {
        config: () => import("@stackra/feature-flags").then((m) => m.ConfigFlagProviderDriver),
        posthog: () =>
          import("@stackra/feature-flags").then((m) => m.PosthogFlagProviderDriver),
      },
    },
    {
      port: Renderer,
      candidates: {
        react: () => import("@stackra/experience/react").then((m) => m.ReactRendererDriver),
      },
    },
    {
      port: OgRenderer,
      candidates: {
        satori: () => import("@stackra/seo/worker").then((m) => m.SatoriOgRendererDriver),
      },
    },
    {
      port: CaptchaVerifier,
      candidates: {
        turnstile: () =>
          import("@stackra/platform/worker").then((m) => m.TurnstileCaptchaVerifierDriver),
      },
    },
  ],
  replaces: [],
  links: [],
  checks: {
    moduleKeys: "unique",
    cycles: "none",
    unexportedInjections: "none",
    unresolvedTypes: "none",
    blockAccepts: "all resolved",
    areas: "public only",
    configsRead: "all",
    overrides: "8 config overrides, each of one base",
    providers: "none (no root module file, so no wrap)",
    prerender: "none (SiteConfig.fixedSiteId unset)",
  },
} satisfies Wiring;
